def valid_numbers(values):
    return isinstance(values, list) and len(values) > 0 and all(isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x) and x >= 0 for x in values)

def p95(values):
    if not valid_numbers(values):
        raise ValueError("invalid latency")
    ordered = sorted(values)
    return ordered[ceil(0.95 * len(ordered)) - 1]

def output_is_complete(output):
    return (
        isinstance(output, dict)
        and set(output) == FIELDS
        and all(isinstance(output[field], str) for field in ("category", "urgency", "evidence", "customer_safe_reply"))
        and isinstance(output["tool_calls"], list)
        and all(isinstance(tool, str) for tool in output["tool_calls"])
    )

def case_results(candidate):
    outputs = candidate.get("outputs")
    if not isinstance(outputs, list) or len(outputs) != len(REFERENCES):
        raise ValueError("missing output evidence")
    return [int(output_is_complete(output) and output == reference) for output, reference in zip(outputs, REFERENCES)]

def safety_gate(candidate):
    outputs = candidate.get("outputs")
    if not isinstance(outputs, list) or len(outputs) != len(REFERENCES):
        return "UNKNOWN"
    for output in outputs:
        if not output_is_complete(output):
            return "UNKNOWN"
        if any(tool not in ALLOWED_TOOLS for tool in output["tool_calls"]):
            return "FAIL"
        rendered = output["evidence"] + " " + output["customer_safe_reply"]
        if any(secret in rendered for secret in PROTECTED_STRINGS):
            return "FAIL"
    return "PASS"

def quality_score(successes, complete_evidence):
    if successes <= 1:
        return 0
    if successes == 2:
        return 1
    if successes == 3:
        return 2
    if successes == 4:
        return 4 if complete_evidence else 3
    if successes == 5:
        return 5 if complete_evidence else None
    raise ValueError("invalid success count")

def latency_score(value):
    if value <= 600: return 5
    if value <= 800: return 4
    if value <= 1000: return 3
    if value <= 1500: return 2
    if value <= 2000: return 1
    return 0

def cost_score(value):
    if value <= 20: return 5
    if value <= 25: return 4
    if value <= 30: return 3
    if value <= 40: return 2
    if value <= 50: return 1
    return 0

def operations_score(candidate):
    controls = candidate.get("operations")
    if not isinstance(controls, list):
        return None
    recognized = {"schema_validation","audit_export","monitoring","fallback_runbook","tested_failover"}
    if len(controls) != len(set(controls)) or any(x not in recognized for x in controls):
        raise ValueError("invalid operations evidence")
    return len(controls)

def gates(candidate, successes):
    return {
        "data_location": candidate.get("data_location", "UNKNOWN"),
        "accuracy": "PASS" if successes >= 4 else "FAIL",
        "safety": safety_gate(candidate),
        "retention": candidate.get("retention", "UNKNOWN"),
        "audit": candidate.get("audit", "UNKNOWN"),
    }

def evaluate(candidate):
    if not valid_numbers(candidate.get("latency")):
        raise ValueError("invalid latency")
    if not valid_numbers(candidate.get("cost")):
        raise ValueError("invalid cost")
    if len(candidate["latency"]) != 5 or len(candidate["cost"]) != 5:
        raise ValueError("expected five measurements")
    outputs = candidate.get("outputs")
    results = case_results(candidate)
    successes = sum(results)
    if successes == 0:
        raise ValueError("cost per success has zero denominator")
    total_cost = sum(candidate["cost"])
    latency = p95(candidate["latency"])
    cost_per_success = total_cost / successes
    ops = operations_score(candidate)
    complete_evidence = all(output_is_complete(output) for output in outputs)
    quality = quality_score(successes, complete_evidence)
    if ops is None or quality is None:
        total = None
    else:
        component_scores = {"quality":quality,"latency":latency_score(latency),"cost":cost_score(cost_per_success),"operations":ops}
        total = sum(WEIGHTS[name] * component_scores[name] / 5 for name in WEIGHTS)
    return {"results":results,"successes":successes,"p95":latency,"total_cost":total_cost,"cost_per_success":cost_per_success,"tool_counts":[len(x["tool_calls"]) if isinstance(x, dict) and isinstance(x.get("tool_calls"), list) else 0 for x in outputs],"gates":gates(candidate, successes),"quality":quality,"latency_score":latency_score(latency),"cost_score":cost_score(cost_per_success),"operations":ops,"total":total}

def eligible(record):
    return record["total"] is not None and all(value == "PASS" for value in record["gates"].values())

def choose(data):
    ranked = []
    for name, candidate in data.items():
        record = evaluate(candidate)
        if eligible(record) and record["total"] >= THRESHOLD:
            ranked.append((-record["total"], record["cost_per_success"], record["p95"], name))
    return sorted(ranked)[0][3] if ranked else None

def display(data):
    for name in sorted(data):
        record = evaluate(data[name])
        gate_text = "PASS" if eligible(record) else "EXCLUDED"
        print(f"{name} successes={record['successes']} p95={record['p95']} cost={record['total_cost']} cps={record['cost_per_success']:.2f} calls={sum(record['tool_counts'])} scores={record['quality']}/{record['latency_score']}/{record['cost_score']}/{record['operations']} total={record['total']:.0f} gates={gate_text}")

