def nonnegative_integer(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValidationError(label + " must be a nonnegative integer")
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValidationError(label + " must be finite")
        if not value.is_integer():
            raise ValidationError(label + " must be an integer")
    if value < 0:
        raise ValidationError(label + " must be nonnegative")
    return int(value)


def finite_number(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValidationError(label + " must be numeric")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValidationError(label + " must be finite")
    return value


def validate_records(records):
    if not isinstance(records, list):
        raise ValidationError("records must be a list")
    seen = set()
    required_fields = {
        "id", "text", "tokens", "mandatory", "status", "trust", "relevance"
    }
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValidationError("record must be a dict at index " + str(index))
        missing = required_fields - set(record)
        if missing:
            raise ValidationError("missing field: " + sorted(missing)[0])
        record_id = record["id"]
        if not isinstance(record_id, str) or not record_id:
            raise ValidationError("id must be a nonempty string")
        if record_id in seen:
            raise ValidationError("duplicate id: " + record_id)
        seen.add(record_id)
        if not isinstance(record["text"], str):
            raise ValidationError("text must be a string: " + record_id)
        record["tokens"] = nonnegative_integer(
            record["tokens"], "tokens for " + record_id
        )
        if not isinstance(record["mandatory"], bool):
            raise ValidationError("mandatory must be boolean: " + record_id)
        if record["status"] not in {"current", "stale"}:
            raise ValidationError("invalid status: " + record_id)
        if record["trust"] not in {"trusted", "untrusted"}:
            raise ValidationError("invalid trust: " + record_id)
        finite_number(record["relevance"], "relevance for " + record_id)


def select(records, budget, reserve):
    working = copy.deepcopy(records)
    validate_records(working)
    budget = nonnegative_integer(budget, "budget")
    reserve = nonnegative_integer(reserve, "reserve")
    if reserve > budget:
        raise ValidationError("reserve exceeds budget")
    usable = budget - reserve

    unavailable = []
    for record in working:
        if record["mandatory"] and (
            record["status"] != "current" or record["trust"] != "trusted"
        ):
            reasons = []
            if record["status"] != "current":
                reasons.append("status=" + record["status"])
            if record["trust"] != "trusted":
                reasons.append("trust=" + record["trust"])
            unavailable.append(record["id"] + "(" + ",".join(reasons) + ")")
    if unavailable:
        raise RequiredEvidenceUnavailable(
            "required evidence unavailable: " + ";".join(unavailable)
        )

    mandatory = [record for record in working if record["mandatory"]]
    mandatory_tokens = sum(record["tokens"] for record in mandatory)
    if mandatory_tokens > usable:
        raise CapacityOverflow(
            "mandatory overflow: " + str(mandatory_tokens - usable)
        )

    optional = sorted(
        (
            record
            for record in working
            if not record["mandatory"]
            and record["status"] == "current"
            and record["trust"] == "trusted"
        ),
        key=lambda record: (-record["relevance"], record["id"]),
    )
    selected = list(mandatory)
    remaining = usable - mandatory_tokens
    for record in optional:
        if record["tokens"] <= remaining:
            selected.append(record)
            remaining -= record["tokens"]

    return {
        "usable": usable,
        "mandatory_tokens": mandatory_tokens,
        "selected": selected,
        "selected_tokens": sum(record["tokens"] for record in selected),
        "remaining": remaining,
    }


def sample_record(**changes):
    record = {
        "id": "sample",
        "text": "Sample evidence.",
        "tokens": 1,
        "mandatory": False,
        "status": "current",
        "trust": "trusted",
        "relevance": 1,
    }
    record.update(changes)
    return record


def expect_error(function, error_type, message_fragment):
    try:
        function()
    except error_type as error:
        assert message_fragment in str(error), (message_fragment, str(error))
    else:
        raise AssertionError("expected " + error_type.__name__)


